"""SCEP challenges (ADR-0019): generated by the server, ``<ID>-<SECRET>``, shown once.

Alphabet ``A-Z0-9`` for devices that choke on anything else (and that sometimes upper-case what
they are given). ID: 8 characters, the public handle to find a challenge without trying them all.
Secret: 32 characters, log2(36) * 32 = 165 bits. Total 41 characters, under the 64 of the RFC 8894
examples and of most device fields. With that entropy SHA-256 is enough (as for the federation
tokens, ADR-0015): a slow hash only protects guessable secrets. Compared in constant time.
"""

import hashlib
import hmac
import re
import secrets
import string
from dataclasses import dataclass

ALPHABET = string.ascii_uppercase + string.digits
ID_LENGTH = 8
SECRET_LENGTH = 32
CHALLENGE = re.compile(rf"^([A-Z0-9]{{{ID_LENGTH}}})-([A-Z0-9]{{{SECRET_LENGTH}}})$")
HASH_PREFIX = "sha256$"


@dataclass(frozen=True, repr=False)
class Challenge:
    identifier: str
    secret: str

    @property
    def text(self) -> str:
        return f"{self.identifier}-{self.secret}"

    def __repr__(self) -> str:
        return f"Challenge({self.identifier}-<redacted>)"


def _random(length: int) -> str:
    return "".join(secrets.choice(ALPHABET) for _ in range(length))


def new_challenge() -> Challenge:
    return Challenge(_random(ID_LENGTH), _random(SECRET_LENGTH))


def parse_challenge(text: str) -> Challenge | None:
    """The challenge in ``text`` (spaces around tolerated), None when it has not the format."""
    match = CHALLENGE.fullmatch(text.strip().upper())
    return Challenge(match[1], match[2]) if match else None


def hash_secret(secret: str) -> str:
    return HASH_PREFIX + hashlib.sha256(secret.encode("ascii")).hexdigest()


def secret_matches(secret: str, stored: str | None) -> bool:
    """Constant time; ``stored = None`` (unknown challenge) still runs one comparison."""
    expected = stored if stored is not None else HASH_PREFIX + "0" * 64
    return hmac.compare_digest(hash_secret(secret), expected) and stored is not None
